insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 4, 'paragraph', 'normal', $t$Christians in Assam are found mostly among the tribal communities.$t$ from public.content where slug = $t$population-census-2011$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 5, 'paragraph', 'normal', $t${{term:scheduled-tribe|Scheduled Tribes}} make up about 12.45% and {{term:scheduled-caste|Scheduled Castes}} about 7.15% of the population.$t$ from public.content where slug = $t$population-census-2011$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 6, 'fact_box', 'exam_fact', $t$Remember for exams: population 3,12,05,576; Hindus 61.47%, Muslims 34.22% (Census 2011).$t$ from public.content where slug = $t$population-census-2011$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$জনসংখ্যা (লোকপিয়ল ২০১১)$t$, $t$অসমত কিমান মানুহ বাস কৰে, আৰু ৰাজ্যখনৰ ধৰ্মীয় গাঁথনি।$t$, 'draft', $t$Assam at a Glance 2025, Directorate of Economics and Statistics, Government of Assam: https://des.assam.gov.in/sites/default/files/swf_utility_folder/departments/ecostat_medhassu_in_oid_3/this_comm/assam_at_a_glance_-_2025.pdf
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'verified_fact', $t$২০১১ চনৰ {{term:census|লোকপিয়ল}} অনুসৰি অসমৰ জনসংখ্যা ৩,১২,০৫,৫৭৬; {{term:population-density|জনসংখ্যাৰ ঘনত্ব}} প্ৰতি বৰ্গ কিমিত ৩৯৮, {{term:sex-ratio|লিংগ অনুপাত}} ৯৫৮ আৰু {{term:literacy-rate|সাক্ষৰতাৰ হাৰ}} ৭২.১৯%। প্ৰায় ৮৬ শতাংশ মানুহ গাঁৱত বাস কৰে।$t$ from public.content where slug = $t$population-census-2011$t$ on conflict do nothing;
