insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 4, 'paragraph', 'normal', $t$অসমৰ খ্ৰীষ্টানসকল বেছিভাগেই জনজাতীয় সম্প্ৰদায়ৰ মাজত আছে।$t$ from public.content where slug = $t$population-census-2011$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 5, 'paragraph', 'normal', $t$জনসংখ্যাৰ প্ৰায় ১২.৪৫% {{term:scheduled-tribe|অনুসূচীত জনজাতি}} আৰু প্ৰায় ৭.১৫% {{term:scheduled-caste|অনুসূচীত জাতি}}।$t$ from public.content where slug = $t$population-census-2011$t$ on conflict do nothing;
