insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 4, 'list', 'verified_fact', $t$Assamese: 1,50,97,257 people (48.38%)
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 5, 'paragraph', 'normal', $t$Counting people who speak it as a second language, more than 71 percent of the people of Assam speak Assamese. Assamese is written in the Assamese script.$t$ from public.content where slug = $t$languages-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 6, 'fact_box', 'exam_fact', $t$Remember for exams: Assamese is the {{term:mother-tongue|mother tongue}} of 48.38% of people (2011); Bodo is also an official language.$t$ from public.content where slug = $t$languages-of-assam$t$ on conflict do nothing;
