insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$অসমীয়া অসমৰ প্ৰধান ভাষা। অসমীয়া আৰু বড়ো ৰাজ্যখনৰ {{term:official-language|চৰকাৰী ভাষা}}, আৰু বৰাক উপত্যকাৰ জিলাসমূহত বাংলা চৰকাৰী ভাষা।$t$ from public.content where slug = $t$languages-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 2, 'paragraph', 'normal', $t$১৯৬০ চনৰ অসম ৰাজ্যিক ভাষা আইনৰ দ্বাৰা অসমীয়াক চৰকাৰী ভাষাৰ মৰ্যাদা দিয়া হয়।$t$ from public.content where slug = $t$languages-of-assam$t$ on conflict do nothing;
