insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 5, 'paragraph', 'normal', $t$দ্বিতীয় ভাষা হিচাপে কোৱাসকলক ধৰিলে অসমৰ ৭১ শতাংশতকৈ অধিক মানুহে অসমীয়া কয়। অসমীয়া ভাষা অসমীয়া লিপিত লিখা হয়।$t$ from public.content where slug = $t$languages-of-assam$t$ on conflict do nothing;
