insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Assam has a mix of {{term:state-university|state universities}}, {{term:central-university|central universities}} and national institutes. These are the ones most often asked about, with their founding year:$t$ from public.content where slug = $t$education-institutions$t$ on conflict do nothing;
