insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 3, 'paragraph', 'normal', $t$Assam's two central universities are Tezpur University and Assam University, Silchar, both set up in 1994.$t$ from public.content where slug = $t$education-institutions$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 4, 'fact_box', 'exam_fact', $t$Remember for exams: Gauhati University 1948; central universities Tezpur and Silchar (1994); IIT Guwahati 1994.$t$ from public.content where slug = $t$education-institutions$t$ on conflict do nothing;
